// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  Img,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type OrganizedCrimeInfographicProps = Record<string, any>;

// --- Helper Component: Image Avatar ---
const MemberAvatar: React.FC<{
  isRecruit: boolean;
  accentColor: string;
  primaryColor: string;
  avatarImage: string;
}> = ({ isRecruit, accentColor, primaryColor, avatarImage }) => {
  const bgColor = isRecruit ? "#ffffff" : "#e2e8f0";
  const borderColor = isRecruit ? accentColor : "#cbd5e1";
  const borderStyle = isRecruit ? "dashed" : "solid";
  const borderWidth = isRecruit ? "3px" : "1px";

  return (
    <div
      style={{
        width: "100%",
        paddingTop: "100%", // 1:1 aspect ratio
        backgroundColor: bgColor,
        borderRadius: "16px",
        position: "relative",
        overflow: "hidden",
        border: `${borderWidth} ${borderStyle} ${borderColor}`,
        boxSizing: "border-box",
      }}
    >
      <Img
        src={avatarImage}
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          objectFit: "cover",
        }}
      />
    </div>
  );
};

const OrganizedCrimeInfographic: React.FC<OrganizedCrimeInfographicProps> = ({
  backgroundColor = "#f8fafc",
  transparentBackground = false,
  durationInSeconds = 10,
  title = "The Modern Cyber Cartel",
  description = "Cybercriminals now operate as highly structured organizations. They employ dedicated HR departments, manage complex payrolls, and run aggressive recruitment campaigns to expand their operations.",
  primaryColor = "#1e293b",
  accentColor = "#3b82f6",
  textColor = "#475569",
  avatarImage = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/d4d289711cb74795bc0e24c555b7747f.png",
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Typography Animations
  const titleOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(frame, [0, 15], [30, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const descOpacity = interpolate(frame, [10, 25], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const descY = interpolate(frame, [10, 25], [20, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Container Animation
  const containerOpacity = interpolate(frame, [20, 35], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Grid Configuration (4 cols, 2 rows)
  // Indices:
  // 0, 1, 2, 3 (3 is the recruit slot)
  // 4, 5, 6, 7
  const gridIndices = [0, 1, 2, 3, 4, 5, 6, 7];

  // Specific Labels to elevate the infographic
  const labelData: Record<number, string> = {
    0: "Leadership",
    4: "Payroll",
    6: "HR Dept.",
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        flexDirection: "row",
        alignItems: "center",
        padding: width * 0.06,
      }}
    >
      {/* Left Column: Text Content */}
      <div
        style={{
          flex: 0.8,
          paddingRight: width * 0.06,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
        }}
      >
        <h1
          style={{
            fontSize: width * 0.045,
            fontWeight: 800,
            lineHeight: 1.1,
            color: primaryColor,
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
            margin: "0 0 24px 0",
            letterSpacing: "-0.02em",
          }}
        >
          {title}
        </h1>
        <p
          style={{
            fontSize: width * 0.018,
            lineHeight: 1.6,
            color: textColor,
            opacity: descOpacity,
            transform: `translateY(${descY}px)`,
            margin: 0,
            maxWidth: "90%",
          }}
        >
          {description}
        </p>
      </div>

      {/* Right Column: Visual Grid */}
      <div style={{ flex: 1.2, position: "relative" }}>
        <div
          style={{
            border: `2px solid #cbd5e1`,
            borderRadius: "32px",
            padding: "48px",
            opacity: containerOpacity,
            backgroundColor: "#f1f5f9",
          }}
        >
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(4, 1fr)",
              gap: "32px",
              position: "relative",
            }}
          >
            {gridIndices.map((index) => {
              const isRecruit = index === 3;

              // Base Members Animation
              const memberDelay = 30 + index * 4;
              const memberScale = spring({
                frame: frame - memberDelay,
                fps,
                config: { damping: 12 },
              });

              // Recruit Animation Logic
              // Start floating outside at frame 80, drop in at frame 110
              const recruitFloatScale = spring({
                frame: frame - 80,
                fps,
                config: { damping: 12 },
              });

              const recruitDropProgress = spring({
                frame: frame - 110,
                fps,
                config: { damping: 14, mass: 0.8 },
              });

              const recruitDropY = interpolate(
                recruitDropProgress,
                [0, 1],
                [-250, 0]
              );
              const recruitDropX = interpolate(
                recruitDropProgress,
                [0, 1],
                [100, 0]
              );

              // Resolve Final Transforms
              const finalScale = isRecruit ? recruitFloatScale : memberScale;
              const finalX = isRecruit ? recruitDropX : 0;
              const finalY = isRecruit ? recruitDropY : 0;
              const zIndex = isRecruit ? 10 : 1;

              // Shadow for floating recruit
              const shadowOpacity = isRecruit
                ? interpolate(recruitDropProgress, [0, 1], [0.15, 0])
                : 0;
              const shadowOffset = isRecruit
                ? interpolate(recruitDropProgress, [0, 1], [20, 0])
                : 0;

              // Label Animation
              const hasLabel = !!labelData[index] || isRecruit;
              const labelText = isRecruit ? "New Recruit" : labelData[index];
              const labelRevealFrame = isRecruit
                ? 130
                : memberDelay + 20;
              const labelOpacity = spring({
                frame: frame - labelRevealFrame,
                fps,
                config: { damping: 12 },
              });

              return (
                <div
                  key={index}
                  style={{
                    transform: `translate(${finalX}px, ${finalY}px) scale(${finalScale})`,
                    zIndex,
                    position: "relative",
                    boxShadow: isRecruit
                      ? `0px ${shadowOffset}px ${shadowOffset * 2}px rgba(0,0,0,${shadowOpacity})`
                      : "none",
                    borderRadius: "16px",
                  }}
                >
                  <MemberAvatar
                    isRecruit={isRecruit}
                    accentColor={accentColor}
                    primaryColor={primaryColor}
                    avatarImage={avatarImage}
                  />

                  {/* Role Labels */}
                  {hasLabel && (
                    <div
                      style={{
                        position: "absolute",
                        bottom: "-40px",
                        left: "50%",
                        transform: "translateX(-50%)",
                        opacity: labelOpacity,
                        fontSize: width * 0.01,
                        fontWeight: 700,
                        whiteSpace: "nowrap",
                        color: isRecruit ? accentColor : primaryColor,
                        backgroundColor: isRecruit
                          ? `${accentColor}1A`
                          : `${primaryColor}1A`,
                        padding: "6px 12px",
                        borderRadius: "8px",
                      }}
                    >
                      {labelText}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default OrganizedCrimeInfographic;